func _load_best() -> void:
	if not FileAccess.file_exists(best_time_path):
		return
	var text := FileAccess.get_file_as_string(best_time_path)
	var parsed = JSON.parse_string(text)
	if not (parsed is Dictionary):
		push_warning("best_time: file is not valid JSON or not a dictionary")
		return
	if parsed.get("format") != "walker-jumpman-clawd.best":
		push_warning("best_time: wrong format field")
		return
	if parsed.get("level") != "first-steps":
		push_warning("best_time: wrong level field")
		return
	var ver = parsed.get("version")
	if not (ver is float or ver is int):
		push_warning("best_time: missing or non-numeric version")
		return
	if int(ver) > 1:
		_best_from_future_version = true
		push_warning("best_time: version %d > 1, ignoring (written by newer build)" % int(ver))
		return
	var bs = parsed.get("best_seconds")
	if not (bs is float or bs is int):
		push_warning("best_time: best_seconds is not a number")
		return
	var bs_float := float(bs)
	if not is_finite(bs_float) or bs_float <= 0.0:
		push_warning("best_time: best_seconds is not a finite number greater than 0")
		return
	best_seconds = bs_float

func _save_best(time: float) -> bool:
	if _best_from_future_version:
		return false
	var data := {"format": "walker-jumpman-clawd.best", "version": 1, "level": "first-steps", "best_seconds": time}
	var tmp_path := best_time_path + ".tmp"
	var file := FileAccess.open(tmp_path, FileAccess.WRITE)
	if file == null:
		push_warning("best_time: cannot write to " + tmp_path)
		return false
	file.store_string(JSON.stringify(data))
	file.close()
	var base_dir := best_time_path.get_base_dir()
	var dir := DirAccess.open(base_dir)
	if dir == null:
		push_warning("best_time: cannot open directory " + base_dir)
		return false
	var err := dir.rename(tmp_path.get_file(), best_time_path.get_file())
	if err != OK:
		push_warning("best_time: rename failed with error " + str(err))
		return false
	return true

